 }
 });
 },
 resetNav() {
 if (this.askAiMode) {
 this.disableAskAiMode();
 return;
 }
 this.selectFirstOrFocus();
 this.focusInput();
 },
 selectFirstOrFocus() {
 if (this.askAiMode) {
 this.activeIndex = -1;
 return;
 }
 const items = this.getNavItems();
 if (items.length) {
 this.activeIndex = 0;
 this.activateNavItem(items);
 } else {
 this.activeIndex = -1;
 }
 },
 activateSelected() {
 const items = this.getNavItems();
 const el = items[this.activeIndex];
 if (el && el.href) {
 el.click();
 return true;
 }
 return false;
 }
 }"
